try:
    exp_paths = [experiment_1_csv, experiment_2_csv, experiment_3_csv, experiment_4_csv, experiment_5_csv]
except NameError:
    # Fallback if not all are defined
    exp_paths = []
    for i in range(1, 6):
        v = globals().get(f'experiment_{i}_csv')
        if v: exp_paths.append(v)

for i, path in enumerate(exp_paths, 1):
    try:
        df = pd.read_csv(path)
        print(f"\n=== Experiment {i} ===")
        print("Columns:", list(df.columns))
        print(df.describe().round(3))
        print(df.head(3))
        num_cols = df.select_dtypes(include='number').columns
        if len(num_cols) >= 2:
